from scipy.stats import norm;K=np.exp(np.linspace(np.log(55),np.log(170),128));d1=(np.log(100/K)+(.05+.5*.2**2))/.2;C=100*norm.cdf(d1)-K*np.exp(-.05)*norm.cdf(d1-.2);ax.plot(K,C,color=ACCENT,label='FFT strike grid');sel=np.array([70,85,100,115,130,150]);d=(np.log(100/sel)+(.05+.5*.2**2))/.2;ax.scatter(sel,100*norm.cdf(d)-sel*np.exp(-.05)*norm.cdf(d-.2),color=WARM,label='Requested strikes');ax.set_xlabel('Strike K (USD)');ax.set_ylabel('Call price (USD)');ax.legend()
